use super::*;
#[test]
fn original_numeric_target_fragments_never_allocate_and_preserve_every_bounded_offset(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in law["cases"].as_array().unwrap(){let key=row["key"].as_u64().unwrap()as u32;let text=row["text"].as_str().unwrap();assert_eq!(unsigned_len(key,0).unwrap(),text.len());for size in 0..12{for offset in 0..=text.len(){let mut output=[0u8;12];let(count,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||read_unsigned(key,0,offset,&mut output[..size]).unwrap());assert_eq!(heap.requested_bytes,0);assert_eq!(heap.released_bytes,0);assert_eq!(&output[..count],&text.as_bytes()[offset..offset+count]);assert_eq!(count,size.min(text.len()-offset));}}assert!(unsigned_len(key,1).is_err());assert!(read_unsigned(key,0,text.len()+1,&mut[]).is_err());assert!(read_unsigned(key,1,0,&mut[]).is_err());}}
